'use client';

import React, { useEffect, useRef, useState, FC, useCallback } from 'react';
import { HierarchyNode } from '@/types/hierarchy';
import { Graph, Node } from '@antv/x6';

type LayoutNode = {
  id: string;
  x: number;
  y: number;
  children?: LayoutNode[];
};
import { Button, Space } from 'antd';
import { Keyboard } from '@antv/x6-plugin-keyboard';
import { Selection } from '@antv/x6-plugin-selection';
import { FullscreenOutlined, ZoomInOutlined, ZoomOutOutlined, ReloadOutlined } from '@ant-design/icons';
import Hierarchy from '@antv/hierarchy';
import LayoutNode from '@antv/hierarchy';


interface MindMapProps {
  data: { root: HierarchyNode };
  prdContent: string;
}

const registerCustomElements = () => {
  Graph.registerNode('topic', {
    inherit: 'rect',
    markup: [
      { tagName: 'rect', selector: 'body' },
      { tagName: 'text', selector: 'label' },
      { tagName: 'title', selector: 'tooltip' }, // 原生 title 备用
    ],
    attrs: {
      body: {
        rx: 6, ry: 6, strokeWidth: 1,
        refWidth: '100%', refHeight: '100%',
        class: 'node-body',
      },
      label: {
        fontSize: 14, fill: '#262626',
        textWrap: { width: -20, height: -10, ellipsis: true },
        textVerticalAnchor: 'middle', textAnchor: 'middle',
        refX: '50%', refY: '50%',
        class: 'node-label',
      },
      tooltip: {
        text: '',  // JS 里会写入
      },
    },
    size: { width: 160, height: 40 },
    autoSize: { width: true, height: true, padding: 15 },
  }, true);

  Graph.registerNode('topic-child', {
    inherit: 'rect',
    markup: [
      { tagName: 'rect', selector: 'body' },
      { tagName: 'text', selector: 'label' },
    ],
    attrs: {
      body: { strokeWidth: 0, refWidth: '100%', refHeight: '100%' },
      label: {
        fontSize: 14, fill: '#262626',
        textVerticalAnchor: 'middle',
        textWrap: { width: -20, height: -10, ellipsis: true },
        refX: '50%', refY: '50%', textAnchor: 'middle',
      },
    },
    size: { width: 160, height: 40 },
    autoSize: { width: true, height: true, padding: 15 },
  }, true);

  Graph.registerNode('topic-leaf', {
    inherit: 'rect',
    markup: [
      { tagName: 'rect', selector: 'body' },
      { tagName: 'text', selector: 'label' },
    ],
    attrs: {
      body: {
        rx: 4, ry: 4, strokeWidth: 1, stroke: '#8c8c8c', fill: '#f5f5f5',
        refWidth: '100%', refHeight: '100%',
      },
      label: {
        fontSize: 13, fill: '#262626',
        textVerticalAnchor: 'middle', textAnchor: 'middle',
        textWrap: { width: -16, height: -8, ellipsis: true },
        refX: '50%', refY: '50%',
      },
    },
    size: { width: 160, height: 30 },
    autoSize: { padding: 10 },
  }, true);

  Graph.registerConnector('mindmap',
    (s, t) => {
      const midX = s.x + 10, midY = s.y;
      const ctrX = (t.x - midX) / 5 + midX, ctrY = t.y;
      return `
        M ${s.x} ${s.y}
        L ${midX} ${midY}
        Q ${ctrX} ${ctrY} ${t.x} ${t.y}
      `;
    }, true);

  Graph.registerEdge('mindmap-edge', {
    inherit: 'edge',
    connector: { name: 'mindmap' },
    attrs: {
      line: { targetMarker: '', stroke: '#A2B1C3', strokeWidth: 2 },
    },
    zIndex: 0,
  }, true);
};

const MindMap: FC<MindMapProps> = ({ data, prdContent }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const graphRef = useRef<Graph | null>(null);
  const tooltipDivRef = useRef<HTMLDivElement | null>(null);
  const [activeTab, setActiveTab] = useState<'mindmap' | 'prd'>('mindmap');
  const [isFullscreen, setIsFullscreen] = useState(false);

  // 初始化 graph + tooltip div
  useEffect(() => {
    if (!containerRef.current) return;

    registerCustomElements();

    // 创建 tooltip DIV，并加入 container 的父元素
    const tooltipDiv = document.createElement('div');
    tooltipDiv.style.position = 'absolute';
    tooltipDiv.style.padding = '6px 10px';
    tooltipDiv.style.background = 'rgba(0,0,0,0.75)';
    tooltipDiv.style.color = '#fff';
    tooltipDiv.style.borderRadius = '4px';
    tooltipDiv.style.pointerEvents = 'none';
    tooltipDiv.style.whiteSpace = 'pre-wrap';
    tooltipDiv.style.fontSize = '12px';
    tooltipDiv.style.display = 'none';
    tooltipDivRef.current = tooltipDiv;
    containerRef.current.parentElement!.appendChild(tooltipDiv);

    const graph = new Graph({
      container: containerRef.current,
      grid: {
        visible: true,
        type: 'doubleMesh',
        args: [
          { color: isFullscreen ? '#444' : '#eee', thickness: 1 },
          { color: isFullscreen ? '#333' : '#ddd', thickness: 1, factor: 4 },
        ],
      },
      panning: { enabled: true },
      mousewheel: { enabled: true, zoomAtMousePosition: true, modifiers: 'ctrl', minScale: 0.2, maxScale: 3 },
    });

    graph.use(new Selection());
    graph.use(new Keyboard());
    graphRef.current = graph;

    // 监听节点 hover 事件
    graph.on('node:mouseenter', ({ node, e }) => {
      const text = node.attr('tooltip/text') as string;
      const rect = containerRef.current!.getBoundingClientRect();
      tooltipDiv.innerText = text;
      tooltipDiv.style.left = `${e.clientX - rect.left + 8}px`;
      tooltipDiv.style.top = `${e.clientY - rect.top + 8}px`;
      tooltipDiv.style.display = 'block';
    });
    graph.on('node:mouseleave', () => {
      tooltipDiv.style.display = 'none';
    });
    graph.on('node:mousemove', ({ e }) => {
      const rect = containerRef.current!.getBoundingClientRect();
      tooltipDiv.style.left = `${e.clientX - rect.left + 8}px`;
      tooltipDiv.style.top = `${e.clientY - rect.top + 8}px`;
    });

    return () => {
      graph.dispose();
      tooltipDiv.remove();
      graphRef.current = null;
    };
  }, [isFullscreen]);

  // 全屏切换后刷新网格
  useEffect(() => {
    const graph = graphRef.current;
    if (!graph) return;
    graph.drawBackground({ color: isFullscreen ? '#000' : '#fff' });
    graph.drawGrid({
      type: 'doubleMesh',
      args: [
        { color: isFullscreen ? '#444' : '#eee', thickness: 1 },
        { color: isFullscreen ? '#333' : '#ddd', thickness: 1, factor: 4 },
      ],
    });
  }, [isFullscreen]);

  const convertToHierarchy = useCallback((node: HierarchyNode): HierarchyNode => {
    const nid =  `n-${Math.random().toString(36).slice(2, 9)}`;
    return { id: nid, text: node.text, children: node.children?.map(convertToHierarchy) };
  }, []);

  const renderMindMap = useCallback(() => {
    const graph = graphRef.current;
    if (!graph || !data.root) return;
    graph.clearCells();

    const root = convertToHierarchy(data.root);

    const createNodes = (n: HierarchyNode, parentId: string | null = null) => {
      console.log(n);
      const isLeaf = !n.children || n.children.length === 0;
      const shape = parentId ? (isLeaf ? 'topic-leaf' : 'topic-child') : 'topic';
      const len = n.id.length;
      const w = Math.max(160, len * 10 + 40);
      const h = isLeaf ? 30 : 40;
      graph.addNode({
        id: n.id,
        shape,
        width: w,
        height: h,
        label: n.text,
        attrs: { tooltip: { text: n.text } },
      });
      if (parentId) {
        graph.addEdge({ source: parentId, target: n.id, shape: 'mindmap-edge' });
      }
      n.children?.forEach(c => createNodes(c, n.id));
    };

    createNodes(root);

    // 布局
    const layout = Hierarchy.mindmap(root, {
      direction: 'H', nodeSep: 100, rankSep: 100,
      getHeight: () => 20, getWidth: () => 100,
      getHGap: () => 80, getVGap: () => 25, getSide: () => 'right',
    });
    const apply = (d: LayoutNode) => {
      (graph.getCellById(d.id) as Node).position(d.x, d.y);
      d.children?.forEach(apply);
    };
    apply(layout);
    graph.centerContent();
  }, [data, convertToHierarchy]);

  // 数据 or tab 切换时渲染
  useEffect(() => {
    if (activeTab !== 'mindmap') return;
    renderMindMap();
  }, [activeTab, renderMindMap]);

  // 视图按钮
  const zoomIn = () => graphRef.current?.zoomTo(Math.min(3, graphRef.current.zoom() + 0.2));
  const zoomOut = () => graphRef.current?.zoomTo(Math.max(0.2, graphRef.current.zoom() - 0.2));
  const resetView = () => {
    const g = graphRef.current;
    if (!g) return;
    const cells = g.getCells();
    if (!cells.length) return;
    const box = g.getCellsBBox(cells)!;
    const { clientWidth: W, clientHeight: H } = g.container;
    const s = Math.min((W - 80) / box.width, (H - 80) / box.height, 1);
    g.zoomTo(s);
    g.translate(W / 2 - (box.x + box.width / 2) * s, H / 2 - (box.y + box.height / 2) * s);
    g.resize();
  };
  const toggleFs = () => {
    const c = containerRef.current;
    if (!c) return;
    if (!document.fullscreenElement) {
      c.requestFullscreen()?.then(() => setIsFullscreen(true));
    } else {
      document.exitFullscreen()?.then(() => setIsFullscreen(false));
    }
  };

  useEffect(() => {
    const onFS = () => {
      setIsFullscreen(!!document.fullscreenElement);
      setTimeout(() => {
        graphRef.current?.resize();
        renderMindMap();
        graphRef.current?.centerContent();
      }, 300);
    };
    window.addEventListener('resize', () => {
      graphRef.current?.resize();
      graphRef.current?.centerContent();
    });
    document.addEventListener('fullscreenchange', onFS);
    return () => {
      document.removeEventListener('fullscreenchange', onFS);
      window.removeEventListener('resize', () => {});
    };
  }, [renderMindMap]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ marginBottom: 16, display: 'flex', justifyContent: 'space-between' }}>
        <div>
          <Button
            type={activeTab === 'mindmap' ? 'primary' : 'default'}
            onClick={() => setActiveTab('mindmap')}
            style={{ marginRight: 8 }}
          >
            Mind Map
          </Button>
          <Button
            type={activeTab === 'prd' ? 'primary' : 'default'}
            onClick={() => setActiveTab('prd')}
          >
            PRD Content
          </Button>
        </div>
        {activeTab === 'mindmap' && (
          <Space>
            <Button icon={<FullscreenOutlined />} onClick={toggleFs} title="Fullscreen" />
            <Button icon={<ZoomInOutlined />} onClick={zoomIn} title="Zoom In" />
            <Button icon={<ZoomOutOutlined />} onClick={zoomOut} title="Zoom Out" />
            <Button icon={<ReloadOutlined />} onClick={resetView} title="Reset View" />
          </Space>
        )}
      </div>
      <div style={{
        flex: 1,
        border: '1px solid #d9d9d9',
        borderRadius: 4,
        overflow: 'hidden',
        backgroundColor: isFullscreen ? '#000' : '#fff',
        position: 'relative',
      }}>
        <div
          ref={containerRef}
          style={{
            width: '100%',
            height: '100%',
            minHeight: '800px',
            display: activeTab === 'mindmap' ? 'block' : 'none',
          }}
        />
        {activeTab === 'prd' && (
          <div style={{ padding: 16, whiteSpace: 'pre-wrap', height: '100%', overflow: 'auto' }}>
            {prdContent}
          </div>
        )}
      </div>
    </div>
  );
};

export default MindMap;
